"""Tool-use rubric.

:class:`ToolRubric` scores rollouts based on tool usage recorded in the
per-rollout ``state`` (e.g. tool messages appended to the completion by a
tool-using environment), in addition to any reward functions supplied by
the caller.
"""

from typing import Any, Callable

from verifiers.parsers import Parser
from verifiers.rubrics.rubric import Rubric
from verifiers.types import RewardFunc, State


class ToolRubric(Rubric):
    """Rubric rewarding tool usage captured in the rollout state.

    In addition to any caller-supplied reward functions, this rubric
    registers per-tool and aggregate reward functions that count tool
    calls and successful tool executions found in the rollout state.

    Attributes:
        tools: Optional list of tool schemas/callables whose per-tool
            reward functions are registered.
    """

    def __init__(
        self,
        parser: Parser | None = None,
        tools: list[Any] | None = None,
        weights: list[float] | None = None,
        **kwargs: Any,
    ):
        """Initialize the tool rubric.

        Args:
            parser: Parser used for answer extraction. Defaults to a plain
                :class:`~verifiers.parsers.Parser`.
            tools: Optional list of tools (schemas or callables) for which
                per-tool usage reward functions are registered.
            weights: Optional weights for the built-in tool reward
                functions; defaults to ``0.0`` each (tracking only).
            **kwargs: Forwarded to :class:`Rubric`.
        """
        super().__init__(parser=parser, **kwargs)
        self.tools = tools or []
        self.tools = [
            self._as_callable_tool(tool) for tool in self.tools
        ]
        reward_funcs: list[RewardFunc] = [
            self.total_tool_calls,
            self.total_tool_successes,
        ]
        for tool in self.tools:
            reward_funcs.append(self._make_tool_reward_func(tool))
        if weights is not None:
            if len(weights) != len(reward_funcs):
                raise ValueError(
                    f"Number of weights ({len(weights)}) must match number of "
                    f"tool reward functions ({len(reward_funcs)})."
                )
            reward_weights = list(weights)
        else:
            reward_weights = [0.0] * len(reward_funcs)
        for func, weight in zip(reward_funcs, reward_weights):
            self.add_reward_func(func, weight)

    @staticmethod
    def _as_callable_tool(tool: Any) -> Callable:
        """Normalize a tool schema/callable into a callable.

        Args:
            tool: A callable, or an object exposing a ``__name__`` or
                ``name`` attribute.

        Returns:
            The tool as a callable (unchanged if already callable).
        """
        return tool if callable(tool) else tool

    def _get_tool_messages(self, state: State) -> list[dict]:
        """Collect tool-role messages from the rollout state.

        Looks at ``state["completion"]`` when present (list of chat
        messages), else at ``state`` itself when it is a list of messages.

        Args:
            state: Mutable per-rollout state dict.

        Returns:
            List of messages (dicts or pydantic objects) with
            ``role == "tool"``.
        """
        completion = state.get("completion", state) if isinstance(state, dict) else state
        if not isinstance(completion, list):
            return []
        messages = []
        for msg in completion:
            role = (
                msg.get("role")
                if isinstance(msg, dict)
                else getattr(msg, "role", None)
            )
            if role == "tool":
                messages.append(msg)
        return messages

    def _get_assistant_tool_calls(self, state: State) -> list[Any]:
        """Collect tool calls made by assistant messages in the state.

        Args:
            state: Mutable per-rollout state dict.

        Returns:
            Flat list of tool-call objects/dicts gathered from the
            ``tool_calls`` field of assistant messages.
        """
        completion = state.get("completion", state) if isinstance(state, dict) else state
        if not isinstance(completion, list):
            return []
        tool_calls: list[Any] = []
        for msg in completion:
            if isinstance(msg, dict):
                role, calls = msg.get("role"), msg.get("tool_calls")
            else:
                role, calls = getattr(msg, "role", None), getattr(
                    msg, "tool_calls", None
                )
            if role == "assistant" and calls:
                tool_calls.extend(calls)
        return tool_calls

    def _tool_call_name(self, tool_call: Any) -> str | None:
        """Extract the tool name from a tool-call object or dict.

        Args:
            tool_call: A tool call (OpenAI pydantic object or dict).

        Returns:
            The invoked tool/function name, or ``None`` if unavailable.
        """
        if isinstance(tool_call, dict):
            function = tool_call.get("function")
            if isinstance(function, dict):
                return function.get("name")
            return tool_call.get("name")
        function = getattr(tool_call, "function", None)
        if function is not None:
            return getattr(function, "name", None)
        return getattr(tool_call, "name", None)

    def total_tool_calls(self, state: State, **kwargs: Any) -> float:
        """Count all tool invocations in the rollout state.

        Counts both tool-role messages (tool results) and tool calls
        recorded on assistant messages, taking the maximum of the two
        views so double-counting is avoided.

        Args:
            state: Mutable per-rollout state dict.
            **kwargs: Ignored extra arguments.

        Returns:
            Number of tool invocations as a float.
        """
        tool_messages = self._get_tool_messages(state)
        tool_calls = self._get_assistant_tool_calls(state)
        return float(max(len(tool_messages), len(tool_calls)))

    def total_tool_successes(self, state: State, **kwargs: Any) -> float:
        """Count tool results that do not indicate an error.

        A tool message is treated as successful unless its content
        contains the substring ``"error"`` (case-insensitive).

        Args:
            state: Mutable per-rollout state dict.
            **kwargs: Ignored extra arguments.

        Returns:
            Number of successful tool results as a float.
        """
        successes = 0
        for msg in self._get_tool_messages(state):
            content = (
                msg.get("content")
                if isinstance(msg, dict)
                else getattr(msg, "content", None)
            )
            if content is None or "error" not in str(content).lower():
                successes += 1
        return float(successes)

    def _make_tool_reward_func(self, tool: Callable) -> RewardFunc:
        """Build a reward function counting invocations of a specific tool.

        Args:
            tool: The tool (callable or schema) to track; its name is read
                from ``__name__`` or ``name``.

        Returns:
            A reward function ``(state, **kwargs) -> float`` returning the
            number of times the tool was invoked in the rollout.
        """
        tool_name = getattr(tool, "__name__", None) or getattr(tool, "name", None)

        def tool_reward_func(state: State, **kwargs: Any) -> float:
            """Count invocations of this specific tool in the state."""
            calls = [
                call
                for call in self._get_assistant_tool_calls(state)
                if self._tool_call_name(call) == tool_name
            ]
            if calls:
                return float(len(calls))
            messages = [
                msg
                for msg in self._get_tool_messages(state)
                if (
                    msg.get("name")
                    if isinstance(msg, dict)
                    else getattr(msg, "name", None)
                )
                == tool_name
            ]
            return float(len(messages))

        if tool_name:
            tool_reward_func.__name__ = f"{tool_name}_tool_calls"
        return tool_reward_func

