    params = sig.parameters
    has_var_keyword = any(
        p.kind == inspect.Parameter.VAR_KEYWORD for p in params.values()
    )
    if has_var_keyword:
        call_args = dict(candidate_args)
    else:
        call_args = {
            k: v for k, v in candidate_args.items() if k in params
        }
    # Fill required parameters not covered by the candidate args
    # (e.g. ``lambda c, **k: ...``) with unused candidate values in
    # canonical order.
    missing = [
        p
        for p in params.values()
        if p.default is inspect.Parameter.empty
        and p.kind
        in (
            inspect.Parameter.POSITIONAL_ONLY,
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
        )
        and p.name not in call_args
    ]
    if missing:
        unused_values = [
            v
            for k, v in candidate_args.items()
            if has_var_keyword or k not in params
        ]
        for param, value in zip(missing, unused_values):
            call_args[param.name] = value
    result = func(**call_args)

